function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const chars = Array.from({ length: n }, () => (rand() < 0.5 ? 'a' : 'b'));
  const mode = rand();
  if (mode < 0.5) chars.sort();
  if (mode < 0.25 && n > 1) {
    const i = Math.floor(rand() * n);
    const j = Math.floor(rand() * n);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
